(function(){'use strict';
const $=id=>document.getElementById(id),P=window.MasteryProfile,MM=window.MasteryMath,MD=window.MASTERY_DATA,D=window.ALBION_DATA;
const catalog=P.catalog(MD,D.recipes,window.GEAR_META,MM),nodes=catalog.flatMap(g=>g.nodes),fmt=(n,d=0)=>Number(n).toLocaleString('ru-RU',{maximumFractionDigits:d}),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let active=false,category='food',search='',branch=null,filledOnly=false,previewId='T8_MEAL_STEW@1';
const panel=document.createElement('section');panel.id='character-content';panel.className='character-content';panel.hidden=true;
panel.innerHTML=`<div class="character-intro"><div><span class="eyebrow">ВАШИ УРОВНИ · ВО ВСЕХ РАСЧЁТАХ</span><h2>Мастерства моего персонажа</h2><p>Заполните уровни с доски достижений. Мастерство ветки и все её специализации вместе определяют расход фокуса.</p></div><span id="character-saved" class="character-saved" role="status">${window.DesktopApp ? "Сохранено на этом компьютере" : "Сохранено в этом браузере"}</span></div><div class="character-tabs" role="tablist" aria-label="Категории мастерств">${P.categories.map(([id,label])=>`<button type="button" role="tab" data-character-category="${id}" aria-controls="character-groups">${label}<small data-category-count="${id}"></small></button>`).join('')}</div><div class="character-layout"><div class="character-editor"><div class="character-toolbar"><label class="field">Найти мастерство<input type="search" id="character-search" placeholder="Например, жаркое, мантия или кирка"></label><label class="check"><input type="checkbox" id="character-filled"> Только заполненные</label></div><p id="character-count" class="hint"></p><div id="character-groups" role="tabpanel"></div></div><aside class="panel character-preview"><span class="eyebrow">КАК УРОВНИ ВЛИЯЮТ НА КРАФТ</span><h2>Ваш расход фокуса</h2><label class="field">Проверить на предмете<select id="character-recipe"></select></label><div id="character-preview-item" class="selected-summary"></div><div class="character-focus-grid"><div><small>На один крафт</small><strong id="character-focus-op"></strong></div><div><small>На один предмет</small><strong id="character-focus-unit"></strong></div></div><p id="character-focus-description" class="hint"></p><div class="character-saving"><span>Экономия фокуса <b id="character-saving-value"></b></span><div class="character-meter"><i id="character-saving-bar"></i></div></div><div class="character-budget"><label class="field">Бюджет фокуса<input id="character-budget" type="number" min="0" max="100000000" step="1000" value="30000"></label><strong id="character-capacity"></strong><small>готовых предметов</small></div><details class="fold"><summary>Из чего складывается эффективность</summary><div id="character-contributions" class="fold-body"></div></details><button type="button" class="button primary" id="character-to-craft">Посчитать этот крафт →</button><p class="hint">Уровни применяются автоматически. В крафте можно отдельно включить ручной ввод эффективности.</p></aside></div>`;
document.querySelector('footer').before(panel);
nodes.find(n=>n.id==='FARM_COOK_MEAT').icon='T8_MEAT';nodes.find(n=>n.id==='FARM_COOK_PRODUCTS').icon='T4_BREAD';nodes.find(n=>n.id==='FARM_ALCHEMIST_ALCOHOL').icon='T8_ALCOHOL';
const branchField=document.createElement('label');branchField.className='field character-branch';branchField.innerHTML='Ветка мастерства<select id="character-branch"></select>';panel.querySelector('.character-toolbar').after(branchField);
function inBranch(g){return search||g.category===category&&(branch==='all'||g.id===branch)}
function branches(){const groups=catalog.filter(g=>g.category===category);if(branch===null||branch!=='all'&&!groups.some(g=>g.id===branch))branch=groups[0]?.id;branchField.hidden=groups.length<2||!!search;$('character-branch').innerHTML='<option value="all">Все ветки категории</option>'+groups.map(g=>`<option value="${g.id}">${esc(g.name)}</option>`).join('');$('character-branch').value=branch;}
$('character-branch').onchange=e=>{branch=e.target.value;render()};
function categoryOf(r){if(r.kind==='food'||r.kind==='potions'||r.kind==='refine')return r.kind;return catalog.find(g=>g.nodes.some(n=>MM.matches(r.id.split('@')[0],n.patterns)))?.category||'accessories'}
function previewOptions(){const options=new Map();if(category==='food')for(const r of D.recipes.filter(r=>r.kind==='food'&&r.tier>=7&&r.ench<=1))options.set(r.id,r);else for(const g of catalog.filter(g=>g.category===category&&(branch==='all'||g.id===branch)))for(const n of g.nodes){const r=D.recipes.find(r=>r.id===n.recipe);if(r)options.set(r.id,r)}
 const selected=D.recipes.find(r=>r.id===previewId);if(selected&&categoryOf(selected)===category&&catalog.some(g=>g.category===category&&(branch==='all'||g.id===branch)&&g.nodes.some(n=>MM.matches(selected.id.split('@')[0],n.patterns))))options.set(selected.id,selected);
 if(!options.has(previewId))previewId=options.keys().next().value;
 $('character-recipe').innerHTML=[...options.values()].map(r=>`<option value="${esc(r.id)}">${esc(r.name)} · T${r.tier}.${r.ench}</option>`).join('');$('character-recipe').value=previewId;
}
function summary(){const levels=window.MasteryUI.levels();
 for(const [id]of P.categories){const list=catalog.filter(g=>g.category===id).flatMap(g=>g.nodes);panel.querySelector(`[data-category-count="${id}"]`).textContent=list.filter(n=>levels[n.id]>0).length+' / '+list.length}
 const visible=catalog.filter(inBranch).flatMap(g=>g.nodes.filter(n=>(n.label+' '+n.name+' '+g.name).toLowerCase().includes(search)&&(!filledOnly||levels[n.id]>0)));
 $('character-count').textContent=`Заполнено ${nodes.filter(n=>levels[n.id]>0).length} из ${nodes.length} мастерств · ${search?'Поиск по всем категориям':P.categories.find(c=>c[0]===category)[1]}: ${visible.length} уровней для ввода. Пустые и нулевые — уровень 0.`;
 for(const input of panel.querySelectorAll('[data-character-level]')){const n=MD.nodes[input.dataset.characterLevel],v=levels[n.id]||0;input.closest('.character-level-card').querySelector('.character-meter i').style.width=v/n.maxLevel*100+'%'}
 for(const group of panel.querySelectorAll('[data-character-group]')){const g=catalog.find(g=>g.id===group.dataset.characterGroup);group.querySelector('.character-group-count').textContent=g.nodes.filter(n=>levels[n.id]>0).length+' / '+g.nodes.length+' заполнено'}
 const r=D.recipes.find(r=>r.id===previewId);if(!r){$('character-focus-op').textContent='—';$('character-focus-unit').textContent='—';$('character-capacity').textContent='—';$('character-to-craft').disabled=true;return}
 const efficiency=MM.efficiency(r,levels,MD),focus=MM.cost(r,efficiency),base=MM.cost(r,0),saving=base?100*(1-focus/base):0;
 $('character-to-craft').disabled=false;$('character-preview-item').innerHTML=window.ItemIcons.image(r.id,1,48)+`<span>${esc(r.name)}<small>T${r.tier}.${r.ench} · ${r.output} шт. за крафт</small></span>`;
 $('character-focus-op').textContent=fmt(focus);$('character-focus-unit').textContent=fmt(focus/r.output,2);$('character-focus-description').textContent=`Эффективность: ${fmt(efficiency)}. Без мастерств: ${fmt(base)} фокуса за крафт.`;
 $('character-saving-value').textContent=fmt(saving,1)+'%';$('character-saving-bar').style.width=Math.max(0,saving)+'%';$('character-capacity').textContent=fmt(Math.floor(Math.max(0,Number($('character-budget').value)||0)/Math.max(1,focus))*r.output);
 const contributions=MM.applicable(r,MD);$('character-contributions').innerHTML=contributions.map(n=>`<div class="character-contribution"><span>${esc(nodes.find(x=>x.id===n.id)?.label==='Общее мастерство'?n.name:nodes.find(x=>x.id===n.id)?.label||n.name)}<small>${levels[n.id]||0} ур. × ${fmt(n.coefficient,2)}</small></span><b>+${fmt((levels[n.id]||0)*n.coefficient)}</b></div>`).join('')||'<p class="hint">Для этого предмета бонусов фокуса нет.</p>';
}
function render(){branches();const levels=window.MasteryUI.levels();panel.querySelectorAll('[data-character-category]').forEach(b=>{const selected=b.dataset.characterCategory===category;b.setAttribute('aria-selected',selected);b.tabIndex=selected?0:-1});
 const groups=catalog.filter(inBranch).map(g=>({...g,nodes:g.nodes.filter(n=>(n.label+' '+n.name+' '+g.name).toLowerCase().includes(search)&&(!filledOnly||levels[n.id]>0))})).filter(g=>g.nodes.length);
 $('character-groups').innerHTML=groups.map(g=>`<section class="character-group" data-character-group="${g.id}"><div class="character-group-heading"><div><h3>${esc(g.name)}</h3><small class="character-group-count"></small></div><span>${esc(P.categories.find(c=>c[0]===g.category)[1])}</span></div><div class="character-level-grid">${g.nodes.map(n=>`<label class="character-level-card ${n.kind==='mastery'?'is-mastery':''}">${n.icon?window.ItemIcons.image(n.icon,1,36):'<span class="character-no-icon">◇</span>'}<span class="character-level-copy"><b>${esc(n.label)}</b><small>${n.kind==='mastery'?'Общий бонус всей ветке':'Специализация'} · 0–${n.maxLevel}</small><span class="character-meter"><i></i></span></span><input type="number" min="0" max="${n.maxLevel}" step="1" value="${levels[n.id]||0}" data-character-level="${n.id}" aria-label="${esc(g.name+' — '+n.label)}"></label>`).join('')}</div></section>`).join('')||'<div class="panel"><h3>Ничего не найдено</h3><p class="hint">Измените название или выключите фильтр «Только заполненные».</p></div>';
 previewOptions();summary();
}
panel.addEventListener('click',e=>{const b=e.target.closest('[data-character-category]');if(b){category=b.dataset.characterCategory;branch=null;search='';$('character-search').value='';render()}});
panel.querySelector('.character-tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const current=P.categories.findIndex(c=>c[0]===category),next=e.key==='Home'?0:e.key==='End'?P.categories.length-1:(current+(e.key==='ArrowRight'?1:-1)+P.categories.length)%P.categories.length;panel.querySelector(`[data-character-category="${P.categories[next][0]}"]`).click();panel.querySelector(`[data-character-category="${category}"]`).focus()});
$('character-search').oninput=e=>{search=e.target.value.trim().toLowerCase();render()};$('character-filled').onchange=e=>{filledOnly=e.target.checked;render()};
panel.addEventListener('input',e=>{if(e.target.dataset.characterLevel)window.MasteryUI.setLevel(e.target.dataset.characterLevel,e.target.value)});
panel.addEventListener('change',e=>{if(e.target.dataset.characterLevel){e.target.value=window.MasteryUI.levels()[e.target.dataset.characterLevel]||0;if(filledOnly)render()}});
$('character-recipe').onchange=e=>{previewId=e.target.value;summary()};$('character-budget').oninput=summary;
$('character-to-craft').onclick=()=>window.CraftApp.open(previewId,{focusSource:'levels',explicitManualFocus:false});
document.addEventListener('masterychange',()=>{if(active)summary()});
const api={active:()=>active,state:{},market:{cancel(){}},refresh(){},render,activate(){active=true;$('craft-content').hidden=true;panel.hidden=false;$('refresh').hidden=true;$('server').disabled=true;document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode==='character'));render()},deactivate(){if(!active)return;active=false;panel.hidden=true;$('craft-content').hidden=false;$('refresh').hidden=false;$('server').disabled=false},open(r){category=categoryOf(r);branch=catalog.find(g=>g.category===category&&g.nodes.some(n=>MM.matches(r.id.split('@')[0],n.patterns)))?.id||null;previewId=r.id;search='';filledOnly=false;$('character-search').value='';$('character-filled').checked=false;document.querySelector('[data-mode="character"]').click();document.dispatchEvent(new Event('change'))}};
window.ActivityViews.character=api;window.CharacterUI=api;
})();
